import 'package:propertylistserialization/propertylistserialization.dart';

var list = [];
var dict = <String, Object>{'Selected': true, 'IconName': 'largeIcon.png', 'IconSize': 32};
list.add(dict);

var xml = PropertyListSerialization.stringWithPropertyList(list);
var back = PropertyListSerialization.propertyListWithString(xml) as List;
